\set ON_ERROR_STOP 1
create or replace function pg_temp.ok(c boolean, m text) returns void language plpgsql as $$ begin if not c then raise exception 'FAIL: %', m; end if; raise notice 'PASS: %', m; end $$;
create or replace function pg_temp.err(sql text) returns text language plpgsql as $$ begin execute sql; return null; exception when others then return sqlerrm; end $$;
grant execute on function pg_temp.ok(boolean,text), pg_temp.err(text) to authenticated;
select set_config('request.jwt.claims','{"email":"weoneaviation8@gmail.com"}',false);
insert into jobs(id,kind,status,input,output) values ('dddddddd-0000-0000-0000-000000000001','reel','running','{}','{}'),('dddddddd-0000-0000-0000-000000000002','reel','running','{}','{}'),('dddddddd-0000-0000-0000-000000000003','reel','running','{}','{}');
update jobs set status='review' where id::text like 'dddddddd%';
select pg_temp.ok((select count(*) from jobs where id::text like 'dddddddd%' and (output->>'review_deadline')::timestamptz between now()+interval '4 min 50 s' and now()+interval '5 min 10 s')=3, 'reaching Review starts a 5-minute window');
select pg_temp.ok(public.auto_approve_due()=0, 'nothing posts before the 5 minutes are up');
set role authenticated;
select public.hold_auto_post('dddddddd-0000-0000-0000-000000000002', true);
select public.set_review_decision('dddddddd-0000-0000-0000-000000000003','approve');
reset role;
select pg_temp.ok((select output->'ig'->>'state' from jobs where id='dddddddd-0000-0000-0000-000000000003')='scheduled' and (select (output->'ig'->>'at')::timestamptz <= now() from jobs where id='dddddddd-0000-0000-0000-000000000003'), 'Approve posts right away');
update jobs set output = output || jsonb_build_object('review_deadline', now() - interval '1 s') where id::text like 'dddddddd%' and status='review';
select pg_temp.ok(public.auto_approve_due()=1, 'after 5 minutes without an answer exactly one reel (not the paused one) is auto-approved');
select pg_temp.ok((select status||'/'||(output->>'decision')||'/'||(output->'ig'->>'state') from jobs where id='dddddddd-0000-0000-0000-000000000001')='done/auto/scheduled', 'unanswered reel -> approved automatically and posting');
select pg_temp.ok((select status from jobs where id='dddddddd-0000-0000-0000-000000000002')='review', 'paused ("Wait, I''m checking") reel is not posted');
set role authenticated;
select public.hold_auto_post('dddddddd-0000-0000-0000-000000000002', false);
reset role;
select pg_temp.ok((select (output->>'review_deadline')::timestamptz > now() + interval '4 min' and output->>'hold' is null from jobs where id='dddddddd-0000-0000-0000-000000000002'), 'Restart timer gives a fresh 5 minutes');
set role authenticated;
select pg_temp.ok(pg_temp.err($$select public.set_autopost(true, 0)$$) like 'The review window%', 'bad window rejected');
select public.set_autopost(false, 10);
reset role;
update jobs set output = output || jsonb_build_object('review_deadline', now() - interval '1 s') where id='dddddddd-0000-0000-0000-000000000002';
select pg_temp.ok(public.auto_approve_due()=0, 'auto-posting switched off: nothing is approved automatically');
set role authenticated; select public.set_autopost(true, 5); reset role;
select 'ALL AUTOPOST DB CHECKS PASSED';
